public(package) fun new<MarketType>(
    interest_model: InterestModel,
    borrow: AssetConfig,
    ctx: &mut TxContext,
): Asset<MarketType> {
    let mut asset = Asset {
        id: object::new(ctx),
        flash_loan_lock: false,
        interest_model,
    };

